package com.booksyde.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID; @Entity @Table(name="publisher_contracts",schema="public") public class PublisherContractEntity{@Id private UUID id;@Column(name="publisher_id",nullable=false)private UUID publisherId;@Column(nullable=false)private String title;@Column(nullable=false)private String status;@Column(name="publisher_percentage",nullable=false)private BigDecimal publisherPercentage;@Column(name="booksyde_percentage",nullable=false)private BigDecimal booksydePercentage;@Column(name="contract_date",nullable=false)private LocalDate contractDate;@Column(name="starts_at",nullable=false)private LocalDate startsAt;@Column(name="ends_at")private LocalDate endsAt;@Column(name="file_path",nullable=false)private String filePath;@Column(name="file_name",nullable=false)private String fileName;private String notes;@Column(name="created_by")private UUID createdBy;@Column(name="created_at",insertable=false,updatable=false)private OffsetDateTime createdAt;protected PublisherContractEntity(){} public UUID getId(){return id;}public UUID getPublisherId(){return publisherId;}public String getTitle(){return title;}public String getStatus(){return status;}public BigDecimal getPublisherPercentage(){return publisherPercentage;}public BigDecimal getBooksydePercentage(){return booksydePercentage;}public LocalDate getContractDate(){return contractDate;}public LocalDate getStartsAt(){return startsAt;}public LocalDate getEndsAt(){return endsAt;}public String getFilePath(){return filePath;}public String getFileName(){return fileName;}public String getNotes(){return notes;}public OffsetDateTime getCreatedAt(){return createdAt;}}
